CODEORG = $76a0
STORYN = 35
; =====================================================================
;  STRONKIE'S ZAPPERS  -  Commodore 64 machine language game
;
;  LOAD"STRONKIES ZAPPERS",8  then  RUN        (self-extracting PRG)
;
;  Controls: joystick in PORT 2 (left/right + fire)  or  A / D / SPACE
;            P = pause, RUN/STOP or RESTORE = back to the menu / BASIC
;
;  Game:     catch ghosts with the proton beam; the quota of a level
;            summons a boss.  Boss caught -> New York map -> next place.
;            Clear Harlem, Manhattan, Harbor and JFK (Statue of Liberty
;            is optional) and you go home: fireworks, flight, Hall of Fame.
;            Every place has its own colours, boss shape, boss attack
;            list (bs_pat) and boss attack speed (bs_int).
;            Ghost types: fast, splitter (shrinks on the first hit), dodger.
;            Weather per place: rain, lightning, fog, thunderstorm.
;            A warning screen announces every boss.
;  Cheat:    type GHOST in the main menu (test mode, no Hall of Fame).
;
;  Sprites:  0 ghost, 1 hunter (animated: stand, walk x2, shoot),
;            2+3 proton beam, 4 slime ball, 5 boss / phantom,
;            6 ghost trap, 7 suction ray
;  SID:      menus = 3 voice Ghostbusters tune (raster IRQ at line 253),
;            game  = riff on voice 1, beam on voice 2, noise/effects on 3
;  Screen:   scrolling New York skyline in extended colour text mode,
;            RAM character set at $3800.  Parallax: a slow far city (rows
;            13-14, own fine scroll) behind the near skyline (rows 15-23);
;            raster splits at lines 154, 166, 238 and 242 (see bodyend)
;  Disk:     HIGHSCORE SEQ file (120 bytes) holds the Top 10
;  Tuned for PAL (50 Hz) machines.
;
;  MEMORY MAP (VIC bank 0 is used for everything the VIC chip reads)
;    $0801-$0c7f  BASIC stub, variables, sprite blocks ($0840 and up)
;    $0c80,$0cc0  plane and map car sprites
;    $0d00-$0e7f  hunter walk / shoot sprites, ghost wobble + mini ghost
;    $0f00-$0fff  boss sprites of Manhattan, Harbor, JFK, Statue
;    $1000-$20a5  Ghostbusters tune (resident, played by the IRQ)
;    $20b0        story text          $2640 flight to New York
;    $2d80        fireworks           $3000 phantom sprite
;    $3040        New York map data   $3800 RAM character set
;    $4000-       data: screens, hall of fame, skyline, intro bitmap
;    CODEORG      main program (address set by build15.py)
;    $a000-$bdff  RAM under BASIC (BASIC is off, $01 = $36):
;                 cutscenes, intro scene, hunter animation, sound effects,
;                 New York progress, places of New York
;    $c000        unpacker (only while starting up)
; =====================================================================

VIC         = $d000
MSBX        = VIC+16
D011        = VIC+17
RASTER      = VIC+18
SPENA       = VIC+21
D016        = VIC+22
SPYEX       = VIC+23
D018        = VIC+24
SPMC        = VIC+28
SPXEX       = VIC+29
COLLISION   = VIC+30
BORDER      = VIC+32
BGCOL       = VIC+33
BGCOL1      = VIC+34
BGCOL2      = VIC+35
BGCOL3      = VIC+36
SPCOL       = VIC+39
SID         = $d400
SIDVOL      = SID+24
OSC3        = SID+27
JOY         = $dc00                 ; joystick port 2
CHROUT      = $ffd2
GETIN       = $ffe4
KEYPRESS    = $c5
KEYBUF      = $c6
CURSORBLINK = $cc
SCREEN      = $0400
COLORRAM    = $d800
SPRPTR      = $07f8
CHARSET     = $3800
PTR         = $fb                   ; zero page pointers
PTR2        = $fd
PMAX        = 160                   ; blaster power: full
PUNLOCK     = 80                    ; overheated blaster works again from here
PDRAIN      = 2                     ; power used per frame of firing
GB          = 12                    ; game border colour: the grey TV bezel
NTILES      = 18
NGTILES     = 142
TMCODE      = 205
STREETCODE  = 165
STREETCOL   = 7

