        .byte 255,16,181,16,132,32,163,16,134,32,162,16,134,32,162,16
        .byte 134,32,162,16,134,32,162,16,134,32,163,16,132,32,255,16
        .byte 255,16,218,16,152,48,144,16,152,48,143,16,154,48,142,16
