        .byte 0,0,0,0,0,0,0,126,0,0,255,0,1,255,128,1
        .byte 153,128,1,219,142,1,255,188,1,231,240,1,231,192,7,231
        .byte 128,63,255,128,113,255,128,33,255,128,1,255,128,1,255,128
        .byte 1,255,128,1,255,128,1,255,128,0,219,0,0,0,0,0
ighostb
        .byte 0,0,0,0,126,0,0,255,0,1,255,128,3,255,192,3
        .byte 255,206,3,255,255,3,255,254,3,255,252,7,255,240,63,255
        .byte 192,127,255,192,255,255,192,115,255,192,35,255,192,3,255,192
