        .text "AMSTERDAM - NEW YORK"
        .byte 0
        .byte $ff
fl_txt2
        .byte 60,4,7
        .text "THE FLIGHT HOME"
        .byte 0
        .byte 221,4,7
        .text "AMSTERDAM"
        .byte 0
        .byte 112,5,7
        .text "NEW YORK"
