sprreset                        ; all sprites back to their game set-up
        lda #spr_ghost/64
        sta SPRPTR
        lda #spr_player/64
        sta SPRPTR+1
        lda #spr_beam/64
        sta SPRPTR+2
        sta SPRPTR+3
        lda #spr_orb/64
        sta SPRPTR+4
        jsr bossptr
        lda #spr_trapc/64
        sta SPRPTR+6
        lda #spr_beam/64
        sta SPRPTR+7
        lda #5
        sta SPCOL
        lda #8
        sta SPCOL+1
        lda #7
        sta SPCOL+2
        sta SPCOL+3
        lda #13
        sta SPCOL+4
        lda #1
        sta SPCOL+5
        lda #12
        sta SPCOL+6
        lda #3
        sta SPCOL+7
        lda #0
        sta SPMC
        sta MSBX
        sta SPXEX
        sta SPYEX
        rts

        * = $2d80               ; free RAM: fireworks of the victory screen
fw_n    .word 0
fw_st   .byte 0,0,0
fw_wt   .byte 0,0,0
fw_cx   .byte 0,0,0
fw_cy   .byte 0,0,0
fw_col  .byte 0,0,0
fw_y    .byte 0,0,0
fw_i    .byte 0
fw_t    .byte 0
fw_mode .byte 0
fw_pc   .byte 0
fw_px   .byte 0
fw_py   .byte 0
fw_r    .byte 0
fw_k    .byte 0
fw_a    .byte 0
fw_ox   .byte 0
fw_oy   .byte 0
fw_q    .byte 0
fw_rn   .byte 0
bon_h   .byte 0
bon_l   .byte 0
fw_ax   .byte 8,8,8,7,6,5,4,3,1,0
fw_ay   .byte 0,1,1,2,3,3,3,4,4,4
fw_ctab .byte 2,7,13,14,10,5,1,8

fwinit  lda #0
        sta fw_t
        sta fw_st
        sta fw_st+1
        sta fw_st+2
        sta fw_wt
        lda #20
        sta fw_wt+1
        lda #40
        sta fw_wt+2
        lda RASTER
        eor $a2
        ora #1
        sta fw_rn
        rts

fwrnd   lda fw_rn
        asl
        bcc fwr1
        eor #$1d
fwr1    sta fw_rn
        rts

fwupd   inc fw_t                ; every third frame all three rockets move on
        lda fw_t
        cmp #3
        bcc fwu9
        lda #0
        sta fw_t
        ldx #2
fwu1    jsr fwslot
        dex
        bpl fwu1
fwu9    rts

fwslot  stx fw_i
        lda fw_st,x
        bne fws1
        lda fw_wt,x             ; waiting for the next rocket
        beq fws0
        dec fw_wt,x
        rts
fws0    jsr fwrnd               ; new rocket: column, burst height, colour
        and #31
        clc
        adc #4
        sta fw_cx,x
        jsr fwrnd
        and #7
        clc
        adc #5
        sta fw_cy,x
        jsr fwrnd
        and #7
        tay
        lda fw_ctab,y
        sta fw_col,x
        lda #23
        sta fw_y,x
        lda #1
        sta fw_st,x
        rts
fws1    cmp #1
        bne fws2
        lda fw_cx,x             ; rocket rising
        sta fw_px
        lda fw_y,x
        sta fw_py
        lda #32
        sta fw_mode
        jsr fwplot
        ldx fw_i
        dec fw_y,x
        lda fw_y,x
        cmp fw_cy,x
        beq fws1e
        bcc fws1e
        sta fw_py
        lda fw_cx,x
        sta fw_px
        lda #42
        sta fw_mode
        lda #1
        sta fw_pc
        jmp fwplot
fws1e   lda #2
        sta fw_st,x
        rts
fws2    sec                     ; burst: erase the old ring, draw the next
        sbc #2
        pha
        lda #32
        sta fw_mode
        pla
        jsr fwring
        ldx fw_i
        lda fw_st,x
        cmp #10
        bne fws3
        lda #0
        sta fw_st,x
        jsr fwrnd
        and #31
        clc
        adc #8
        sta fw_wt,x
        rts
fws3    lda fw_col,x
        ldy fw_st,x
        cpy #8
        bcc fws4
        lda #11                 ; the sparks die out grey
fws4    sta fw_pc
        lda #42
        sta fw_mode
        lda fw_st,x
        sec
        sbc #1
        jsr fwring
        ldx fw_i
        inc fw_st,x
        rts

fwring  sta fw_r                ; ring of radius A around the burst centre (0 = nothing)
        bne fwr_go
        rts
fwr_go
        ldy #9
fwr_l   sty fw_k
        lda fw_ax,y
        sta fw_a
        lda #0
        ldx fw_r
fwr_a   clc
        adc fw_a
        dex
        bne fwr_a
        lsr
        lsr
        sta fw_ox
        ldy fw_k
        lda fw_ay,y
        sta fw_a
        lda #0
        ldx fw_r
fwr_b   clc
        adc fw_a
        dex
        bne fwr_b
        lsr
        lsr
        sta fw_oy
        ldx fw_i
        lda #3
        sta fw_q
fwr_q   lda fw_q
        and #1
        bne fwr_xm
        lda fw_cx,x
        clc
        adc fw_ox
        cmp #40
        bcs fwr_n
        jmp fwr_xs
fwr_xm  lda fw_cx,x
        sec
        sbc fw_ox
        bcc fwr_n
fwr_xs  sta fw_px
        lda fw_q
        and #2
        bne fwr_ym
        lda fw_cy,x
        clc
        adc fw_oy
        cmp #25
        bcs fwr_n
        jmp fwr_ys
fwr_ym  lda fw_cy,x
        sec
        sbc fw_oy
        bcc fwr_n
fwr_ys  sta fw_py
        jsr fwplot
        ldx fw_i
fwr_n   dec fw_q
        bpl fwr_q
        ldy fw_k
        dey
        bmi fwrx
        jmp fwr_l
fwrx    rts

fwplot  ldy fw_py               ; spark only on empty cells (or on sparks): the text stays on top
        lda nm_rlo,y
        clc
        adc fw_px
        sta PTR
        lda nm_rhi,y
        adc #0
        sta PTR+1
        ldy #0
        lda (PTR),y
        cmp #32
        beq fwp1
        cmp #42
        bne fwp9
fwp1    lda fw_mode
        sta (PTR),y
        lda PTR+1
        clc
        adc #$d4
        sta PTR+1
        lda fw_pc
        sta (PTR),y
fwp9    rts

winbonus                        ; 1000 points for every life left
        lda #0
        sta bon_h
        sta bon_l
        ldx lives
        beq wb9
        sei
wb1     sed
        clc
        lda scl
        adc #0
        sta scl
        lda sch
        adc #$10
        sta sch
        bcc wb2
        lda #$99                ; the score stops at 9999
        sta sch
        sta scl
wb2     clc
        lda bon_h
        adc #$10
        sta bon_h
        cld
        dex
        bne wb1
        cli
wb9     jmp hmclr

